function thumbnail(id){const url=data.templates[id]?.thumbnail_url;try{const u=new URL(url);return u.protocol==='https:'?esc(u.href):'./assets/exercise-fallback.svg';}catch{return './assets/exercise-fallback.svg';}}
function refresh(){stats=calculate(data,period);$('#date-range').textContent=`${fmt(stats.start)} — ${fmt(stats.end)}`;renderList();renderDetails();colorModel();}
function renderList(){const scroll=$('#muscle-list').scrollTop,left=$('#muscle-list').scrollLeft;$('#muscle-list').innerHTML=GROUPS.map((g,i)=>`<button class="muscle-card ${g.id===selected?'active':''}" data-muscle="${g.id}" aria-label="${g.name}, ${stats.results[g.id].primary} direct sets" aria-pressed="${g.id===selected}"><span class="index">${String(i+1).padStart(2,'0')}</span>${thumbs.has(g.id)?`<img src="${thumbs.get(g.id)}" alt="">`:'<span class="placeholder" aria-hidden="true"></span>'}<span class="count">${stats.results[g.id].primary}</span><span class="name">${g.name}</span></button>`).join('');$('#muscle-list').scrollTop=scroll;$('#muscle-list').scrollLeft=left;$('#muscle-list').querySelectorAll('button').forEach(b=>b.onclick=()=>selectMuscle(selected===b.dataset.muscle?null:b.dataset.muscle,true));}
function allExercises(){return Object.values(stats.results).flatMap(r=>Object.values(r.exercises).filter(e=>e.role==='primary')).sort((a,b)=>b.count-a.count);}
function regionResult(r){const ex=Object.values(r.exercises).filter(e=>e.role==='primary'&&exerciseEmphasis(selected,e.title)===region);const weekly=Array(stats.bins).fill(0),sessions=new Set();for(const e of ex)for(const h of e.history){sessions.add(h.workoutId);const index=Math.min(stats.bins-1,Math.floor((Date.parse(h.date)-stats.start)/86400000/stats.days*stats.bins));weekly[index]+=h.sets.filter(s=>activeSet(s)&&s.type!=='dropset').length;}return {primary:ex.reduce((s,e)=>s+e.count,0),secondary:0,drops:ex.reduce((s,e)=>s+e.drops,0),sessions,weekly,exercises:Object.fromEntries(ex.map(e=>[e.id,e]))};}
