 if(!selected){const ranked=GROUPS.map(g=>({...g,n:stats.results[g.id].primary})).sort((a,b)=>b.n-a.n).slice(0,5);const max=ranked[0]?.n||1;$('#overview-bars').innerHTML=ranked.map(g=>`<button class="overview-row" data-id="${g.id}"><span>${g.name}</span><i><b style="width:${g.n/max*100}%"></b></i><span>${g.n}</span></button>`).join('');$('#overview-bars').querySelectorAll('button').forEach(b=>b.onclick=()=>selectMuscle(b.dataset.id));}
 const max=Math.max(1,...r.weekly);$('#weekly-chart').innerHTML=r.weekly.map((n,i)=>`<div class="week-col"><span class="week-value">${n}</span><div class="week-bar" style="height:${Math.max(1,n/max*47)}px"></div><span class="week-label">${period==='7'?new Date(stats.start+i*86400000).getUTCDate():fmt(stats.start+Math.floor(i*stats.days/stats.bins)*86400000)}</span></div>`).join('');$('#weekly-chart').setAttribute('aria-label',r.weekly.map((n,i)=>`${fmt(stats.start+Math.floor(i*stats.days/stats.bins)*86400000)}: ${n} sets`).join('; '));
