function selectMuscle(id,focus=true,sub=null){selected=id;region=sub;role='primary';$('#hover-name').style.display='none';renderList();renderDetails();colorModel();if(ready&&focus){side=id?groups.get(id).view:'front';if(id==='shoulders'&&sub==='rear')side='back';updateSide();id?focusMuscle(id):fullView();}}
