$('#all-body').onclick=$('#clear-selection').onclick=()=>selectMuscle(null);$('#range').onchange=e=>{period=e.target.value;refresh();};for(const r of ['primary','secondary'])$('#'+r+'-tab').onclick=()=>{role=r;renderDetails();};
