 const starGeo=new THREE.BufferGeometry(),p=[];let seed=41;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<380;i++)p.push((rand()-.5)*5,rand()*3-.5,-.7-rand()*1.5);starGeo.setAttribute('position',new THREE.Float32BufferAttribute(p,3));scene.add(new THREE.Points(starGeo,new THREE.PointsMaterial({color:0x92aaa1,size:.004,transparent:true,opacity:.5,depthWrite:false})));
